list_trash.code:
var response = await client.Trash.ListTrashAsync(new Dictionary<string, object?>
{
    ["type"] = "Category", ["search"] = "spring", ["sort"] = "name", ["order"] = "asc", ["limit"] = 20,
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var item in ((IReadOnlyList<object?>)body["items"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{item["id"]} {item["type"]} {item["name"]} {item["updated"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

