bulk_restore_trash.code:
var response = await client.Trash.BulkRestoreTrashAsync(new Dictionary<string, object?>
{
    ["items"] = new object[]
    {
        new Dictionary<string, object?> { ["type"] = "Category", ["id"] = 1234 },
        new Dictionary<string, object?> { ["type"] = "BlogPost", ["id"] = 99 },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
Console.WriteLine($"{body["restored"]} {body["failed"]}");
foreach (var error in ((IReadOnlyList<object?>)body["errors"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{error["type"]} {error["id"]} {error["reason"]}");

